def fnv1a_intermediate(data):
    """Returns the final edx value (byte XOR hash) after processing all bytes"""
    hash_val = 0x811c9dc5
    edx = 0
    for byte in data:
        edx = byte ^ hash_val
        hash_val = (edx * 0x1000193) & 0xFFFFFFFF
    return edx & 0xFFFFFFFF

